insert into public.services (
  slug, name, category, icon, blurb, introduction, helps_with,
  intended_audience, general_approach, first_appointment, faqs,
  related_service_slugs, sort_order, is_active
) values
  ('child-counselling', 'Child Counselling', 'counselling', 'Baby', 'A safe space for children to talk about feelings, school and friendships.', 'A supportive place for a child to express what is on their mind, shaped around their age and family context.', '["Adjusting to changes at home or school", "Talking about worries, feelings or friendships", "Expressing needs"]'::jsonb, 'Children, with caregiver involvement planned with the family.', 'Conversation, play-based or creative activities may be used with appropriate caregiver involvement.', 'The first meeting explores what brings the family in, introduces the child to the process and discusses privacy and next steps.', '[{"question":"Does a caregiver attend?","answer":"The practitioner will discuss this with the family based on age, comfort and the reason for the visit."},{"question":"How can I prepare my child?","answer":"Explain that they will meet someone who listens and talks with children; avoid promising a particular result."},{"question":"Will I receive updates?","answer":"The practitioner will agree what can be shared while respecting the child’s privacy and safety."}]'::jsonb, array['family-counselling','special-education','behavioral-management'], 10, true),
  ('pre-marital-counselling', 'Pre-Marital Counselling', 'counselling', 'HeartHandshake', 'Guided conversations for couples preparing for life together.', 'A structured setting for couples to discuss expectations and changes they anticipate as they build a life together.', '["Discussing communication styles and expectations", "Exploring shared decisions", "Making space for difficult conversations"]'::jsonb, 'Partners considering or preparing for marriage or a long-term commitment.', 'Sessions use listening, guided discussion and practical communication exercises chosen with the couple.', 'Both partners can share what they hope to discuss and ask about privacy and participation.', '[{"question":"Do both partners attend?","answer":"Joint attendance is usually helpful; contact the clinic to discuss other circumstances."},{"question":"Do we need to prepare topics?","answer":"No. You may bring topics, and the practitioner can help decide where to begin."},{"question":"Is counselling only for couples in conflict?","answer":"No. Some couples use sessions to discuss expectations before a major commitment."}]'::jsonb, array['marital-counselling','family-counselling'], 20, true),
  ('marital-counselling', 'Marital Counselling', 'counselling', 'Heart', 'Support for couples working through communication and change.', 'A neutral setting for partners to discuss concerns, understand perspectives and consider possible next steps.', '["Communication that feels difficult", "Adjusting to relationship or family changes", "Clarifying needs and shared decisions"]'::jsonb, 'Married partners who wish to work on relationship concerns together.', 'The practitioner supports respectful conversation; focus and pace are agreed with the couple.', 'The first session covers each partner’s perspective, what prompted the visit and confidentiality.', '[{"question":"Can one partner attend alone?","answer":"Contact the clinic to discuss an individual first meeting and whether it fits your goals."},{"question":"Will the practitioner take sides?","answer":"The intention is to understand both perspectives and support a fair conversation."},{"question":"What if we are unsure about continuing?","answer":"Use the first visit to ask questions and decide whether the approach feels suitable."}]'::jsonb, array['pre-marital-counselling','family-counselling'], 30, true),
  ('family-counselling', 'Family Counselling', 'counselling', 'Users', 'Help for families to understand each other and ease strain.', 'A supported space for family members to discuss concerns, hear one another and consider day-to-day changes.', '["Family communication", "Changes in roles or routines", "Ways to support one another"]'::jsonb, 'Families or selected family members with shared concerns.', 'The family and practitioner decide who attends and what to prioritise; sessions may include practical communication strategies.', 'Each person can share their view and discuss who should attend future sessions.', '[{"question":"Does everyone attend?","answer":"No. The family and practitioner can decide who is appropriate to include."},{"question":"Can children attend?","answer":"This depends on the child, topic and family circumstances; discuss it when arranging a visit."},{"question":"Will everyone have room to speak?","answer":"The practitioner will aim to make room for each person and keep discussion respectful."}]'::jsonb, array['child-counselling','marital-counselling','old-age-counselling'], 40, true),
  ('old-age-counselling', 'Old Age Counselling', 'counselling', 'Sunset', 'Compassionate support through life transitions in later years.', 'A respectful space for older adults to discuss changes, relationships, wellbeing and personal priorities.', '["Life transitions", "Loneliness, loss or family concerns", "Sources of support and meaning"]'::jsonb, 'Older adults, with family involvement only when wanted and appropriate.', 'The practitioner listens to the person’s priorities and adapts pace and format where possible.', 'The first visit covers priorities, communication preferences and practical access needs; a trusted person may join if wanted.', '[{"question":"Can a family member come?","answer":"Yes, if the client wants this; the practitioner will check how they should be involved."},{"question":"Can I discuss a recent change?","answer":"Sessions can offer space to talk through a change and consider support options."},{"question":"Should I bring medical information?","answer":"Bring only information you think is relevant; the practitioner can explain what may be useful."}]'::jsonb, array['family-counselling','marital-counselling'], 50, true),
  ('occupational-therapy', 'Occupational Therapy', 'rehabilitation', 'Hand', 'Building the skills needed for play, learning and everyday tasks.', 'Support for participation in meaningful everyday activities, planned around routines, goals and environment.', '["Practising everyday tasks", "Participating in play, learning or self-care", "Exploring adaptations for daily activities"]'::jsonb, 'Children or adults seeking support with activities that matter to them.', 'The therapist may discuss goals, observe activities and practise selected tasks; suggestions are tailored to the person.', 'The first visit discusses routines, priorities and access needs; any activity is agreed with the person.', '[{"question":"Should I bring anything?","answer":"Relevant reports or examples may help; contact the clinic to ask what is useful."},{"question":"Will I practise at home?","answer":"The therapist may suggest activities that fit the person’s goals and routine."},{"question":"Can a caregiver attend?","answer":"A caregiver may join when helpful and with the client’s agreement."}]'::jsonb, array['adl-training','special-education','cognitive-management'], 60, true),
  ('speech-therapy', 'Speech Therapy', 'rehabilitation', 'MessageCircle', 'Support for speech, language and communication.', 'Support for communication and, where relevant, aspects of eating or swallowing, based on the person’s goals.', '["Speech, language or communication practice", "Communicating needs and ideas", "Communication in daily settings"]'::jsonb, 'Children or adults seeking support with communication or related needs.', 'Conversation, structured activities and practical strategies may be used; goals are discussed with the client.', 'The first visit discusses strengths, concerns and communication in everyday settings; any assessment is explained first.', '[{"question":"Is an assessment always done at the first visit?","answer":"Not necessarily. The therapist will discuss useful information and agree next steps."},{"question":"Can caregivers participate?","answer":"Yes, when appropriate and agreed; their observations may help connect practice with daily routines."},{"question":"Will there be practice activities?","answer":"The therapist may suggest activities based on goals and what is practical."}]'::jsonb, array['occupational-therapy','special-education','cognitive-management'], 70, true),
  ('special-education', 'Special Education', 'rehabilitation', 'BookOpen', 'Learning support planned around each child’s needs.', 'Individualised learning support that takes account of a child’s strengths, interests and current learning needs.', '["Practising learning skills at an individual pace", "Supporting participation in learning", "Coordinating goals with family or school when agreed"]'::jsonb, 'Children who would benefit from individualised learning support.', 'The educator discusses priorities and plans activities at a suitable level; goals are revisited with the family.', 'The family can share the child’s interests, learning experiences and priorities; school materials are optional.', '[{"question":"Is a school referral required?","answer":"Ask the clinic about its intake process; a school plan may be helpful if available."},{"question":"Will the educator contact the school?","answer":"School contact should be discussed with the family and arranged with permission."},{"question":"How are goals chosen?","answer":"Goals are discussed with the family and shaped by the child’s priorities and learning context."}]'::jsonb, array['child-counselling','occupational-therapy','speech-therapy'], 80, true),
  ('behavioral-management', 'Behavioral Management', 'rehabilitation', 'Compass', 'Practical strategies for challenging behaviour at home and school.', 'Support to understand behaviour in context and develop respectful, practical approaches to participation and communication.', '["Understanding patterns around difficult moments", "Planning consistent responses", "Communicating expectations and needs"]'::jsonb, 'Children, adults and caregivers seeking practical support with behaviour in daily life.', 'The practitioner considers routines and context and works with the person or caregivers on appropriate, reviewable strategies.', 'The first visit explores situations of concern, what has been tried and who should be involved.', '[{"question":"Is the approach based on punishment?","answer":"The focus is on context and supportive, respectful responses, not punishment."},{"question":"Should caregivers attend?","answer":"Caregiver participation may help when strategies involve home routines."},{"question":"Can strategies be discussed for school?","answer":"Yes; school coordination should be agreed with the family and relevant permissions."}]'::jsonb, array['child-counselling','family-counselling','special-education'], 90, true),
  ('cognitive-management', 'Cognitive Management', 'rehabilitation', 'Brain', 'Exercises and strategies for attention, memory and thinking skills.', 'Structured practice and everyday strategies related to attention, memory and planning.', '["Remembering everyday information", "Practising attention or planning", "Adapting routines for daily tasks"]'::jsonb, 'People seeking support with thinking skills in daily activities.', 'The practitioner discusses meaningful activities and may use structured tasks or practical routine changes.', 'The first visit explores daily activities, what feels difficult and existing assessments if available.', '[{"question":"Does this service provide a diagnosis?","answer":"No. Ask the clinic about referral options if an assessment is needed."},{"question":"Are sessions the same for everyone?","answer":"No. Activities are selected around the person’s priorities and daily situations."},{"question":"Can family members help?","answer":"A family member may participate with the person’s agreement when useful."}]'::jsonb, array['occupational-therapy','adl-training','speech-therapy'], 100, true),
  ('adl-training', 'ADL Training', 'rehabilitation', 'Home', 'Training in daily living skills such as dressing, eating and self-care.', 'Supported practice with daily tasks based on the person’s goals, preferences and environment.', '["Practising self-care routines", "Breaking tasks into manageable steps", "Exploring tools or adaptations"]'::jsonb, 'Children or adults seeking practical support with everyday self-care tasks.', 'The practitioner discusses preferences and may practise selected steps in a respectful setting.', 'The person can describe priorities and access needs; proposed activities are explained before practice.', '[{"question":"Do I have to practise every task?","answer":"No. The person chooses what they are comfortable discussing or practising."},{"question":"Can family members learn how to help?","answer":"With the person’s agreement, a family member can discuss supportive approaches."},{"question":"Can equipment be discussed?","answer":"Possible tools or adaptations may be discussed based on individual needs and context."}]'::jsonb, array['occupational-therapy','cognitive-management'], 110, true)
on conflict (slug) do update set
  name = excluded.name,
  category = excluded.category,
  icon = excluded.icon,
  blurb = excluded.blurb,
  introduction = excluded.introduction,
  helps_with = excluded.helps_with,
  intended_audience = excluded.intended_audience,
  general_approach = excluded.general_approach,
  first_appointment = excluded.first_appointment,
  faqs = excluded.faqs,
  related_service_slugs = excluded.related_service_slugs,
  sort_order = excluded.sort_order,
  is_active = excluded.is_active;